<style>
.tts-buy-box {
  background: linear-gradient(135deg, #1a0533 0%, #2d0a5e 100%);
  border: 1px solid rgba(180,0,255,0.4);
  border-radius: 16px;
  padding: 28px 24px;
  max-width: 380px;
  font-family: sans-serif;
  color: #fff;
}
.tts-buy-box h3 {
  font-size: 20px;
  font-weight: 700;
  margin: 0 0 6px;
  color: #fff;
}
.tts-buy-box .tts-subtitle {
  font-size: 13px;
  color: rgba(255,255,255,0.6);
  margin-bottom: 20px;
}
.tts-price-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: rgba(255,255,255,0.07);
  border-radius: 10px;
  padding: 12px 16px;
  margin-bottom: 12px;
}
.tts-price-label { font-size: 12px; color: rgba(255,255,255,0.55); }
.tts-price-value { font-size: 18px; font-weight: 700; color: #e040fb; }
.tts-info-row {
  display: flex;
  justify-content: space-between;
  margin-bottom: 20px;
  gap: 10px;
}
.tts-info-box {
  flex: 1;
  background: rgba(255,255,255,0.06);
  border-radius: 10px;
  padding: 10px 12px;
  text-align: center;
}
.tts-info-box .label { font-size: 11px; color: rgba(255,255,255,0.5); margin-bottom: 4px; }
.tts-info-box .value { font-size: 14px; font-weight: 600; color: #fff; }
.tts-buy-btn {
  display: block;
  width: 100%;
  background: linear-gradient(135deg, #e040fb, #7c4dff);
  color: #fff;
  font-size: 16px;
  font-weight: 700;
  padding: 14px;
  border-radius: 12px;
  text-align: center;
  text-decoration: none;
  margin-bottom: 10px;
  border: none;
  cursor: pointer;
  transition: opacity 0.2s;
}
.tts-buy-btn:hover { opacity: 0.88; }
.tts-chart-btn {
  display: block;
  width: 100%;
  background: rgba(255,255,255,0.08);
  color: rgba(255,255,255,0.8);
  font-size: 14px;
  font-weight: 600;
  padding: 11px;
  border-radius: 12px;
  text-align: center;
  text-decoration: none;
  border: 1px solid rgba(255,255,255,0.15);
  transition: background 0.2s;
}
.tts-chart-btn:hover { background: rgba(255,255,255,0.14); }
.tts-contract {
  margin-top: 16px;
  background: rgba(0,0,0,0.25);
  border-radius: 8px;
  padding: 10px 12px;
  font-size: 11px;
  color: rgba(255,255,255,0.45);
  word-break: break-all;
  text-align: center;
}
.tts-contract span { color: rgba(255,255,255,0.7); font-weight: 600; }
.tts-network-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  background: rgba(0,132,255,0.2);
  border: 1px solid rgba(0,132,255,0.4);
  border-radius: 20px;
  padding: 3px 10px;
  font-size: 11px;
  color: #4da6ff;
  font-weight: 600;
  margin-bottom: 16px;
}
.tts-dot { width: 6px; height: 6px; background: #4da6ff; border-radius: 50%; display: inline-block; animation: pulse 1.5s infinite; }
@keyframes pulse { 0%,100%{opacity:1} 50%{opacity:0.4} }
</style>

<div class="tts-buy-box">
  <div class="tts-network-badge">
    <span class="tts-dot"></span>
    Live on Base Blockchain
  </div>
  <h3>Buy $TTS Now</h3>
  <p class="tts-subtitle">New users receive $5 in free TTS on signup</p>

  <div class="tts-price-row">
    <span class="tts-price-label">Current Price</span>
    <span class="tts-price-value">$0.01 USD</span>
  </div>

  <div class="tts-info-row">
    <div class="tts-info-box">
      <div class="label">Target Price</div>
      <div class="value"></div>
    </div>
    <div class="tts-info-box">
      <div class="label">Total Supply</div>
      <div class="value">69B TTS</div>
    </div>
    <div class="tts-info-box">
      <div class="label">LP Locked</div>
      <div class="value">12 Months</div>
    </div>
  </div>

  <a class="tts-buy-btn" href="https://app.uniswap.org/swap?outputCurrency=0x5570eA97d53A53170e973894A9Fa7feb5785d3b9&chain=base" target="_blank">
    🔥 Buy $TTS on Uniswap
  </a>

  <a class="tts-chart-btn" href="https://dexscreener.com/base/0x77Fe188379BEaAd3BCFb26c965c812CEa721ce68" target="_blank">
    📈 View Live Chart on DexScreener
  </a>

  <div class="tts-contract">
    <span>Contract:</span> 0x5570eA97d53A53170e973894A9Fa7feb5785d3b9
  </div>
